attributes.visState:
{"title": "Successful logins map", "type": "vega", "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "config": {
    "kibana": {
      "type": "map",
      "latitude": 20,
      "longitude": 0,
      "zoom": 2
    }
  },
  "data": [
    {
      "name": "places",
      "url": {
        "index": "wazuh-events-v5*",
        "%context_query%": "@timestamp",
        "body": {
          "size": 0,
          "query": {
            "bool": {
              "must": [
                "%dashboard_context-must_clause%"
              ],
              "filter": [
                {
                  "term": {
                    "event.category": "authentication"
                  }
                },
                {
                  "term": {
                    "event.outcome": "success"
                  }
                },
                {
                  "term": {
                    "wazuh.integration.name": "ns8"
                  }
                }
              ],
              "must_not": [
                "%dashboard_context-must_not_clause%",
                {
                  "terms": {
                    "process.executable": [
                      "/usr/bin/crond",
                      "/usr/sbin/cron",
                      "/usr/lib/systemd/systemd"
                    ]
                  }
                },
                {
                  "terms": {
                    "event.action": [
                      "service-logon",
                      "machine-logon"
                    ]
                  }
                }
              ]
            }
          },
          "aggs": {
            "countries": {
              "terms": {
                "field": "source.geo.country_name",
                "size": 50
              },
              "aggs": {
                "cities": {
                  "terms": {
                    "field": "source.geo.city_name",
                    "size": 100,
                    "missing": "-"
                  },
                  "aggs": {
                    "where": {
                      "geo_centroid": {
                        "field": "source.geo.location"
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.countries.buckets"
      },
      "transform": [
        {
          "type": "flatten",
          "fields": [
            "cities.buckets"
          ],
          "as": [
            "city"
          ]
        },
        {
          "type": "geopoint",
          "projection": "projection",
          "fields": [
            "city.where.location.lon",
            "city.where.location.lat"
          ]
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "size",
      "type": "sqrt",
      "domain": {
        "data": "places",
        "field": "city.doc_count"
      },
      "range": [
        60,
        1500
      ]
    }
  ],
  "signals": [
    {
      "name": "pick",
      "on": [
        {
          "events": "symbol:click",
          "update": "datum.city.key == '-' ? kibanaAddFilter({match_phrase: {'source.geo.country_name': datum.key}}, 'wazuh-events-v5*') : kibanaAddFilter({match_phrase: {'source.geo.city_name': datum.city.key}}, 'wazuh-events-v5*')"
        }
      ]
    }
  ],
  "marks": [
    {
      "type": "symbol",
      "from": {
        "data": "places"
      },
      "encode": {
        "update": {
          "x": {
            "field": "x"
          },
          "y": {
            "field": "y"
          },
          "size": {
            "scale": "size",
            "field": "city.doc_count"
          },
          "fill": {
            "value": "#2e9e4f"
          },
          "fillOpacity": {
            "value": 0.6
          },
          "stroke": {
            "value": "#1b5e30"
          },
          "cursor": {
            "value": "pointer"
          },
          "tooltip": {
            "signal": "{title: datum.city.key == '-' ? datum.key : datum.city.key + ', ' + datum.key, 'Logins': datum.city.doc_count}"
          }
        }
      }
    }
  ]
}"}, "aggs": []}
